"""Whole basic/advanced reciprocal setup and the runtime/JIT contracts."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='정수 나눗셈 · 사전 계산·JIT',
                     sections=sections, questions=questions))


add('lib/math/reciprocal_div.c', '역수 나눗셈 준비 전체: 곱셈 계수와 시프트 계산',
    '같은 제수로 여러 번 나눌 때 제수에 의존하는 계산을 미리 수행합니다.',
    '기본 reciprocal_value는 d에서 곱셈 계수 m과 두 시프트를 구합니다. 고급 reciprocal_value_adv는 계수의 상하 경계를 줄여 JIT 코드 생성에 쓸 계수·시프트·폭 정보를 반환합니다.',
    '제수0은 지원하지 않습니다. 기본 경로와 고급 경로의 입력 범위가 같다고 가정하지 말고,고급 경로의 prec도 생성할 코드의 피제수 정밀도와 맞춰야 합니다.',
    [('전체 파일', 'SPDX와 bitops/bug/export/limits/math/minmax/types/reciprocal_div 헤더,설명을 헤더로 안내하는 주석,두 준비 함수와 각 export가 전부입니다. 실제 기본 나눗셈의 빠른 경로는 헤더에 있습니다.'),
     ('기본 계수 계산', 'l=fls(d-1)은 양의 d에 대해 ceil(log2(d))입니다. m=floor(2^32*(2^l-d)/d)+1을 u64에서 계산하고 하위32비트를 R.m에 저장합니다. sh1=min(l,1),sh2=max(l-1,0)입니다. do_div는 준비 단계에서 실제 나눗셈을 수행하므로 전체 방식에 나눗셈이 전혀 없다는 뜻은 아닙니다.'),
     ('기본 예제', 'd=1이면 l=0,m=1,sh1=0,sh2=0입니다. 빠른 경로의 t는 모든 u32 a에 대해0이라 결과a입니다. d=3이면 l=2,m=1431655766,sh1=1,sh2=1입니다. a=10이면 t=3이고(3+((10-3)>>1))>>1=3입니다.'),
     ('고급 경계와 축소', '고급 함수는 l과 post_shift를 구하고 mlow=floor(2^(32+l)/d),mhigh=floor((2^(32+l)+2^(32+l-prec))/d)를 만듭니다. 매 단계 둘을 반으로 옮겼을 때 lo<hi가 유지되면 갱신하고 post_shift를 줄입니다. lo>=hi이면 더 줄이지 않습니다. mhigh의 하위32비트,남은 시프트,원래 지수l,32비트 초과 여부를 반환합니다.'),
     ('경고와 사전 조건', 'l==32일 때 WARN을 호출하지만 함수 실행을 종료하지는 않습니다. 뒤의1ULL<<(32+l)은64비트 폭 경계를 넘으므로 경고를 입력 검증·복구로 해석하면 안 됩니다. 헤더는 큰 제수를 호출 전에 따로 처리하도록 설명합니다. prec도 u8이라는 이유만으로 모든0..255 값이 안전한 것은 아니며 시프트 범위를 지켜야 합니다.'),
     ('CS와 비용 배분', '기본 방식은 준비 비용을 반복 나눗셈에서 나누어 부담하는 상각 관점입니다. 고급 방식은 JIT 생성 시 더 많은 계산을 해도 생성된 코드가 여러 번 실행될 때 이득을 얻을 수 있다는 절충입니다. 모든 CPU·호출 횟수에서 항상 빠르다는 벤치마크 결론은 이 파일만으로 내리지 않습니다.')],
    [('reciprocal_value(3)의 계수와 시프트는?', 'm=1431655766,sh1=1,sh2=1', 'm=3,sh1=0,sh2=0', 'l=2이고 floor(2^32/3)+1=1431655766입니다. 계수는 제수 그 자체가 아닙니다.'),
     ('고급 함수의 WARN(l==32)이 잘못된 입력의 실행을 막는가?', '아니다. 경고 뒤 계산이 계속되므로 호출 전에 처리해야 한다', '그렇다. 자동으로 안전한 결과를 반환한다', 'WARN 다음에 return이 없습니다. 뒤의 시프트 계산이 유효하도록 호출자가 예외를 처리해야 합니다.'),
     ('기본 준비 단계에도 나눗셈이 있는가?', '있다. do_div로 계수를 계산한다', '없다. 준비와 실행이 모두 곱셈만 한다', '실제 나눗셈을 준비 단계로 옮겨 같은 제수의 반복 실행에서 재사용하는 방식입니다.')])

add('include/linux/reciprocal_div.h', '역수 나눗셈 헤더 전체: 정확한 몫과 코드 생성 계약',
    '역수 계수는 부동소수점 근사값을 단순히 곱하는 것이 아니라 정수 몫을 재현하는 표현입니다.',
    '기본 구조체의 m,sh1,sh2로 t=high32(a*m)를 구하고(t+((a-t)>>sh1))>>sh2를 반환합니다. 고급 구조체는 m,sh,exp,is_wide_m을 담고 사용법을 의사 코드로 설명합니다.',
    '계수는 해당 제수로 준비한 값을 사용해야 합니다. 임의 구조체 값이나0 제수로 정확한 결과가 보장되지는 않습니다. 고급 의사 코드는 실제 함수가 아니라 코드 생성 안내입니다.',
    [('전체 구성', 'SPDX,guard,types.h,알고리즘 출처와 목적 주석,기본 구조체·준비 선언·인라인 실행 함수,고급 구조체·상세 의사 코드·준비 선언으로 구성됩니다. 고급 reciprocal_divide_adv라는 실행 함수는 이 헤더에 없습니다.'),
     ('기본 빠른 경로', 'a를 u64로 확장하여 m과 곱하고 상위32비트를 t로 얻습니다. 이후 보정 덧셈과 시프트로 정수 나눗셈의 내림 몫을 만듭니다. d=3,a=10의 결과는3입니다. 동일한 d의 준비 결과를 재사용해야 준비 비용 절약이 가능합니다.'),
     ('큰 제수와2의 거듭제곱', '헤더의 의사 코드는 d>=2^31이면 n>=d라는 비교로 결과를 구합니다. u32 피제수의 몫은 이 범위에서0 또는1뿐입니다.2의 거듭제곱 제수는 exp만큼 오른쪽 이동하여 처리할 수 있습니다. 큰 제수 예외 처리는 고급 준비 함수를 호출하기 전입니다.'),
     ('고급의 넓은 계수', 'is_wide_m은 계산한 mhigh가 U32_MAX보다 큰지를 나타냅니다. 실제 구조체 m은 하위32비트만 저장하므로 이 플래그에 따른 추가 보정이 필요합니다. 넓은 계수이고 제수가 짝수이면 d의 최하위1비트 위치를 pre_shift로 구해2의 인수를 먼저 제거하고,줄어든 정밀도로 다시 준비하는 경로가 설명되어 있습니다.'),
     ('의사 코드 읽기', '주석의 imm은 코드 생성에서 제수 상수를 뜻하는 문맥이며 독립 선언된 C 변수가 아닙니다. 일반 분기에서 pre_shift가0이면 result=n 초기값을 준비해야 하고,상위32비트 곱에는(u64)n 같은 확장이 필요합니다. 세미콜론도 생략된 예이므로 그대로 복사한 완성 C 프로그램으로 간주하지 않습니다.'),
     ('검증 범위와 CS', '사전 계산된 메타데이터,상수 나눗셈 최적화,고정 폭 곱의 상위 절반,JIT 생성 비용과 실행 비용을 연결합니다. 기본 경로는 실제 u32 나눗셈과 비교하고,고급 경로는 설명된 분기를 명시적으로 구현한 별도 실행 모델로 비교할 수 있습니다. 그 모델의 통과가 실제 모든 JIT 백엔드의 정확성을 증명하지는 않습니다.')],
    [('고급 구조체 m만 곱하면 모든 경우가 처리되는가?', '아니다. is_wide_m과 시프트·예외 분기를 고려해야 한다', '그렇다. 나머지 필드는 디버그 정보다', 'mhigh가32비트를 넘으면 m에는 하위 비트만 남습니다. 별도 보정 정보를 무시하면 다른 계산이 됩니다.'),
     ('u32 n에서 d>=2^31인 나눗셈의 몫은?', '0 또는1', '최대2^31', 'n의 최대값은2^32-1로2*d보다 작습니다. 따라서 n>=d 여부로 몫을 구할 수 있습니다.'),
     ('헤더에 고급 나눗셈의 완성된 실행 함수가 있는가?', '없다. 준비 함수 선언과 사용 의사 코드가 있다', '있다. reciprocal_divide_adv가 구현되어 있다', '실제 인라인 실행 함수는 기본 reciprocal_divide 하나입니다. 고급 부분은 JIT 등에서 사용할 생성 절차를 설명합니다.')])
